请对以下 case 进行三维加权评分。

=== case_id ===
Case-21-stocks-002

=== 用户原始指令 (query.txt) ===
弄个基金走势图嘛,主体是图,显示收益数字,点跳应用,大跌提醒我

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个基金走势图嘛,主体是图,显示收益数字,点跳应用,大跌提醒我",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "fund": {
      "name": {
        "type": "string",
        "description": "基金名称或基金简称",
        "sampleValue": "成长混合"
      },
      "returnText": {
        "type": "string",
        "description": "当前收益数字展示文本",
        "sampleValue": "+2.36%"
      },
      "returnLabel": {
        "type": "string",
        "description": "收益统计周期说明",
        "sampleValue": "近一月收益"
      },
      "statusText": {
        "type": "string",
        "description": "大跌提醒状态短文本",
        "sampleValue": "大跌提醒"
      },
      "statusDetail": {
        "type": "string",
        "description": "大跌提醒触发条件或说明",
        "sampleValue": "跌幅超3%提醒"
      },
      "updateText": {
        "type": "string",
        "description": "行情数据更新时间展示文本",
        "sampleValue": "14:30更新"
      },
      "trendScore": {
        "type": "number",
        "description": "走势图主进度数值，用于表达阶段收益趋势强度",
        "sampleValue": 68
      },
      "trendTotal": {
        "type": "number",
        "description": "走势图主进度总量",
        "sampleValue": 100
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bell_fill.svg",
      "description": "铃铛实心图标，适合用于通知提醒、大跌提醒或消息提示状态。"
    }
  ]
}

